// src/components/modals/ChangeProjectStatusModal.jsx
import React, { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { 
  Clock, TrendingUp, CheckCircle, Pause, XCircle, 
  AlertCircle, Info
} from 'lucide-react';

const STATUS_OPTIONS = [
  {
    value: 'planning',
    label: 'Planificación',
    description: 'El proyecto está en fase de planificación',
    icon: Clock,
    color: 'bg-yellow-100 text-yellow-700 border-yellow-300',
    iconColor: 'text-yellow-600',
  },
  {
    value: 'in_progress',
    label: 'En Progreso',
    description: 'El proyecto está siendo ejecutado activamente',
    icon: TrendingUp,
    color: 'bg-blue-100 text-blue-700 border-blue-300',
    iconColor: 'text-blue-600',
  },
  {
    value: 'on_hold',
    label: 'Pausado',
    description: 'El proyecto está temporalmente detenido',
    icon: Pause,
    color: 'bg-gray-100 text-gray-700 border-gray-300',
    iconColor: 'text-gray-600',
  },
  {
    value: 'completed',
    label: 'Completado',
    description: 'Todas las tareas han sido completadas',
    icon: CheckCircle,
    color: 'bg-green-100 text-green-700 border-green-300',
    iconColor: 'text-green-600',
  },
  {
    value: 'cancelled',
    label: 'Cancelado',
    description: 'El proyecto ha sido cancelado',
    icon: XCircle,
    color: 'bg-red-100 text-red-700 border-red-300',
    iconColor: 'text-red-600',
  },
];

export const ChangeProjectStatusModal = ({ 
  isOpen, 
  onClose, 
  project,
  onStatusChange 
}) => {
  const [selectedStatus, setSelectedStatus] = useState(project?.status || 'planning');
  const [loading, setLoading] = useState(false);

  // Calcular estado sugerido
  const calculateSuggestedStatus = () => {
    if (!project?.tasks || project.tasks.length === 0) return 'planning';
    
    const totalTasks = project.tasks.length;
    const completedTasks = project.tasks.filter(t => t.status === 'completed').length;
    const progress = (completedTasks / totalTasks) * 100;
    
    if (progress === 100) return 'completed';
    if (progress > 0) return 'in_progress';
    return 'planning';
  };

  const suggestedStatus = calculateSuggestedStatus();

  const handleSubmit = async () => {
    setLoading(true);
    try {
      await onStatusChange(selectedStatus);
      onClose();
    } catch (error) {
      console.error('Error changing status:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      {/* ✅ MAX WIDTH Y HEIGHT RESPONSIVE */}
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Cambiar Estado del Proyecto</DialogTitle>
        </DialogHeader>

        <div className="py-4 space-y-4">
          {/* Estado Actual */}
          <div className="p-4 bg-gray-50 rounded-lg">
            <p className="text-sm text-gray-600 mb-2">Estado Actual</p>
            <Badge className={`border ${STATUS_OPTIONS.find(s => s.value === project?.status)?.color}`}>
              {STATUS_OPTIONS.find(s => s.value === project?.status)?.label}
            </Badge>
          </div>

          {/* Sugerencia del Sistema */}
          {suggestedStatus !== project?.status && (
            <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg flex items-start gap-3">
              <Info className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold text-blue-900 mb-1">
                  Sugerencia del Sistema
                </p>
                <p className="text-sm text-blue-700 mb-2">
                  Según el progreso de tareas ({Math.round((project?.tasks?.filter(t => t.status === 'completed').length || 0) / (project?.tasks?.length || 1) * 100)}%), 
                  se recomienda cambiar a: <strong>{STATUS_OPTIONS.find(s => s.value === suggestedStatus)?.label}</strong>
                </p>
                <Button
                  onClick={() => setSelectedStatus(suggestedStatus)}
                  variant="outline"
                  size="sm"
                  className="text-blue-700 border-blue-300 hover:bg-blue-100"
                >
                  Aplicar Sugerencia
                </Button>
              </div>
            </div>
          )}

          {/* Opciones de Estado - SCROLLABLE */}
          <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2">
            <p className="text-sm font-medium text-gray-700 mb-3 sticky top-0 bg-white pb-2">
              Selecciona el nuevo estado:
            </p>
            
            {STATUS_OPTIONS.map((status) => {
              const StatusIcon = status.icon;
              const isSelected = selectedStatus === status.value;
              const isSuggested = suggestedStatus === status.value;

              return (
                <button
                  key={status.value}
                  onClick={() => setSelectedStatus(status.value)}
                  className={`w-full p-3 sm:p-4 rounded-lg border-2 transition-all text-left ${
                    isSelected
                      ? 'border-green-500 bg-green-50 shadow-md'
                      : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
                  }`}
                >
                  <div className="flex items-center justify-between gap-2">
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                      <div className={`p-2 rounded-lg flex-shrink-0 ${status.color}`}>
                        <StatusIcon className={`w-4 h-4 sm:w-5 sm:h-5 ${status.iconColor}`} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <h4 className="font-semibold text-gray-900 text-sm sm:text-base">
                            {status.label}
                          </h4>
                          {isSuggested && status.value !== project?.status && (
                            <Badge variant="outline" className="text-xs bg-blue-50 text-blue-700 border-blue-300">
                              Sugerido
                            </Badge>
                          )}
                        </div>
                        <p className="text-xs sm:text-sm text-gray-600 mt-1 line-clamp-2">
                          {status.description}
                        </p>
                      </div>
                    </div>

                    {isSelected && (
                      <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0" />
                    )}
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        {/* ✅ FOOTER STICKY */}
        <DialogFooter className="sticky bottom-0 bg-white pt-4 border-t">
          <Button variant="outline" onClick={onClose}>
            Cancelar
          </Button>
          <Button 
            onClick={handleSubmit}
            disabled={loading || selectedStatus === project?.status}
            className="bg-green-600 hover:bg-green-700"
          >
            {loading ? 'Guardando...' : 'Cambiar Estado'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
